   205→    /// Sets a dynamic precompile lookup function that is called for addresses not found
   206→    /// in the static precompile map.
   207→    ///
   208→    /// This method allows you to provide runtime-resolved precompiles that aren't known
   209→    /// at initialization time. The lookup function is called whenever a precompile check
   210→    /// is performed for an address that doesn't exist in the main precompile map.
   211→    ///
   212→    /// # Important Notes
   213→    ///
   214→    /// - **Priority**: Static precompiles take precedence. The lookup function is only called if
   215→    ///   the address is not found in the main precompile map.
   216→    /// - **Gas accounting**: Addresses resolved through this lookup are always treated as cold,
   217→    ///   meaning they incur cold access costs even on repeated calls within the same transaction.
   218→    ///   See also [`PrecompileProvider::warm_addresses`].
   219→    /// - **Performance**: The lookup function is called on every precompile check for
   220→    ///   non-registered addresses, so it should be efficient.
   221→    ///
   222→    /// # Example
   223→    ///
   224→    /// ```ignore
   225→    /// precompiles.set_precompile_lookup(|address| {
   226→    ///     // Dynamically resolve precompiles based on address pattern
   227→    ///     if address.as_slice().starts_with(&[0xDE, 0xAD]) {
   228→    ///         Some(DynPrecompile::new(|input| {
   229→    ///             // Custom precompile logic
   230→    ///             Ok(PrecompileOutput {
   231→    ///                 gas_used: 100,
   232→    ///                 bytes: Bytes::from("dynamic precompile"),
   233→    ///             })
   234→    ///         }))
   235→    ///     } else {
   236→    ///         None
   237→    ///     }
   238→    /// });
   239→    /// ```
   240→    pub fn set_precompile_lookup<L>(&mut self, lookup: L)
   241→    where
   242→        L: PrecompileLookup + 'static,
   243→    {
   244→        self.lookup = Some(Arc::new(lookup));
   245→    }
   246→
   247→    /// Builder-style method to set a dynamic precompile lookup function.
   248→    ///
   249→    /// This is a consuming version of [`set_precompile_lookup`](Self::set_precompile_lookup)
   250→    /// that returns `Self` for method chaining.
   251→    ///
   252→    /// See [`set_precompile_lookup`](Self::set_precompile_lookup) for detailed behavior,
   253→    /// important notes, and examples.
   254→    pub fn with_precompile_lookup<L>(mut self, lookup: L) -> Self
   255→    where
   256→        L: PrecompileLookup + 'static,
   257→    {
   258→        self.set_precompile_lookup(lookup);
   259→        self
   260→    }
   261→
   262→    /// Consumes the type and returns a set of [`DynPrecompile`].
   263→    pub fn into_dyn_precompiles(mut self) -> DynPrecompiles {
   264→        self.ensure_dynamic_precompiles();
   265→        match self.precompiles {
   266→            PrecompilesKind::Dynamic(dynamic) => dynamic,
   267→            _ => unreachable!("We just ensured that this is a Dynamic variant"),
   268→        }
   269→    }
   270→
   271→    /// Ensures that precompiles are in their dynamic representation.
   272→    /// If they are already dynamic, this is a no-op.
   273→    /// Returns a mutable reference to the dynamic precompiles.
   274→    pub fn ensure_dynamic_precompiles(&mut self) -> &mut DynPrecompiles {
   275→        if let PrecompilesKind::Builtin(ref precompiles_cow) = self.precompiles {
   276→            let mut dynamic = DynPrecompiles::default();
   277→
   278→            let static_precompiles = match precompiles_cow {
   279→                Cow::Borrowed(static_ref) => static_ref,
   280→                Cow::Owned(owned) => owned,
   281→            };
   282→
   283→            for (&addr, pc) in static_precompiles.inner().iter() {
   284→                dynamic.inner.insert(addr, DynPrecompile::from(*pc.precompile()));
   285→                dynamic.addresses.insert(addr);
   286→            }
   287→
   288→            self.precompiles = PrecompilesKind::Dynamic(dynamic);
   289→        }
   290→
   291→        match &mut self.precompiles {
   292→            PrecompilesKind::Dynamic(dynamic) => dynamic,
   293→            _ => unreachable!("We just ensured that this is a Dynamic variant"),
   294→        }
   295→    }
   296→
   297→    /// Returns an iterator over references to precompile addresses.
   298→    pub fn addresses(&self) -> impl Iterator<Item = &Address> {
   299→        match &self.precompiles {
   300→            PrecompilesKind::Builtin(precompiles) => Either::Left(precompiles.addresses()),
   301→            PrecompilesKind::Dynamic(dyn_precompiles) => {
   302→                Either::Right(dyn_precompiles.addresses.iter())
   303→            }
   304→        }
   305→    }
   306→
   307→    /// Gets a reference to the precompile at the given address.
   308→    ///
   309→    /// This method first checks the static precompile map, and if not found,
   310→    /// falls back to the dynamic lookup function (if set).
   311→    pub fn get(&self, address: &Address) -> Option<impl Precompile + '_> {
   312→        // First check static precompiles
   313→        let static_result = match &self.precompiles {
   314→            PrecompilesKind::Builtin(precompiles) => precompiles.get(address).map(Either::Left),
   315→            PrecompilesKind::Dynamic(dyn_precompiles) => {
   316→                dyn_precompiles.inner.get(address).map(Either::Right)
   317→            }
   318→        };
   319→
   320→        // If found in static precompiles, wrap in Left and return
   321→        if let Some(precompile) = static_result {
   322→            return Some(Either::Left(precompile));
   323→        }
   324→
   325→        // Otherwise, try the lookup function if available
   326→        let lookup = self.lookup.as_ref()?;
   327→        lookup.lookup(address).map(Either::Right)
   328→    }
   329→}
