   349→impl<BlockEnv, TxEnv, CfgEnv, DB, Chain>
   350→    PrecompileProvider<Context<BlockEnv, TxEnv, CfgEnv, DB, Journal<DB>, Chain>> for PrecompilesMap
   351→where
   352→    BlockEnv: revm::context::Block,
   353→    TxEnv: revm::context::Transaction,
   354→    CfgEnv: revm::context::Cfg,
   355→    DB: Database,
   356→{
   357→    type Output = InterpreterResult;
   358→
   359→    fn set_spec(&mut self, _spec: CfgEnv::Spec) -> bool {
   360→        false
   361→    }
   362→
   363→    fn run(
   364→        &mut self,
   365→        context: &mut Context<BlockEnv, TxEnv, CfgEnv, DB, Journal<DB>, Chain>,
   366→        address: &Address,
   367→        inputs: &InputsImpl,
   368→        _is_static: bool,
   369→        gas_limit: u64,
   370→    ) -> Result<Option<InterpreterResult>, String> {
   371→        // Get the precompile at the address
   372→        let Some(precompile) = self.get(address) else {
   373→            return Ok(None);
   374→        };
   375→
   376→        let mut result = InterpreterResult {
   377→            result: InstructionResult::Return,
   378→            gas: Gas::new(gas_limit),
   379→            output: Bytes::new(),
   380→        };
   381→
   382→        let (local, journal) = (&context.local, &mut context.journaled_state);
   383→
   384→        // Execute the precompile
   385→        let r;
   386→        let input_bytes = match &inputs.input {
   387→            CallInput::SharedBuffer(range) => {
   388→                // `map_or` does not work here as we use `r` to extend lifetime of the slice
   389→                // and return it.
   390→                #[allow(clippy::option_if_let_else)]
   391→                if let Some(slice) = local.shared_memory_buffer_slice(range.clone()) {
   392→                    r = slice;
   393→                    &*r
   394→                } else {
   395→                    &[]
   396→                }
   397→            }
   398→            CallInput::Bytes(bytes) => bytes.as_ref(),
   399→        };
   400→
   401→        let precompile_result = precompile.call(PrecompileInput {
   402→            data: input_bytes,
   403→            gas: gas_limit,
   404→            caller: inputs.caller_address,
   405→            value: inputs.call_value,
   406→            internals: EvmInternals::new(journal, &context.block),
   407→            target_address: inputs.target_address,
   408→            bytecode_address: inputs.bytecode_address.expect("always set for precompile calls"),
   409→        });
   410→
   411→        match precompile_result {
   412→            Ok(output) => {
   413→                let underflow = result.gas.record_cost(output.gas_used);
   414→                assert!(underflow, "Gas underflow is not possible");
   415→                result.result = if output.reverted {
   416→                    InstructionResult::Revert
   417→                } else {
   418→                    InstructionResult::Return
   419→                };
   420→                result.output = output.bytes;
   421→            }
   422→            Err(PrecompileError::Fatal(e)) => return Err(e),
   423→            Err(e) => {
   424→                result.result = if e.is_oog() {
   425→                    InstructionResult::PrecompileOOG
   426→                } else {
   427→                    InstructionResult::PrecompileError
   428→                };
   429→            }
   430→        };
   431→
   432→        Ok(Some(result))
   433→    }
   434→
   435→    fn warm_addresses(&self) -> Box<impl Iterator<Item = Address>> {
   436→        Box::new(self.addresses().copied())
   437→    }
   438→
   439→    fn contains(&self, address: &Address) -> bool {
   440→        self.get(address).is_some()
   441→    }
   442→}
