   584→/// Trait for implementing precompiled contracts.
   585→#[auto_impl::auto_impl(&, Arc)]
   586→pub trait Precompile {
   587→    /// Returns precompile ID.
   588→    fn precompile_id(&self) -> &PrecompileId;
   589→
   590→    /// Execute the precompile with the given input data, gas limit, and caller address.
   591→    fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult;
   592→
   593→    /// Returns whether the precompile is pure.
   594→    ///
   595→    /// A pure precompile has deterministic output based solely on its input.
   596→    /// Non-pure precompiles may produce different outputs for the same input
   597→    /// based on the current state or other external factors.
   598→    ///
   599→    /// # Default
   600→    ///
   601→    /// Returns `true` by default, indicating the precompile is pure
   602→    /// and its results should be cached as this is what most of the precompiles are.
   603→    ///
   604→    /// # Examples
   605→    ///
   606→    /// Override this method to return `false` for non-deterministic precompiles:
   607→    ///
   608→    /// ```ignore
   609→    /// impl Precompile for MyDeterministicPrecompile {
   610→    ///     fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult {
   611→    ///         // non-deterministic computation dependent on state
   612→    ///     }
   613→    ///
   614→    ///     fn is_pure(&self) -> bool {
   615→    ///         false // This precompile might produce different output for the same input
   616→    ///     }
   617→    /// }
   618→    /// ```
   619→    fn is_pure(&self) -> bool {
   620→        true
   621→    }
   622→}
